Object.assign(MILESTONE_DETAILS,{"41": {"keywords": ["KV State / Reuse"], "authors": "见原论文与精读笔记", "affiliation": "研究对象与机制见下文", "motivation": "重复文档位于不同前文之后，连续前缀不能覆盖这些复用。", "design": "独立文档 KV、位置校正与选择性 token 重算，并重叠加载和计算。", "result": "原生 RAG 的 QA／摘要实验同时评价质量与 TTFT；我们的多轮迁移结果见实验进展。", "limitations": "额外独立构建、修复和搬运必须计入；追加历史完整驻留时原生前缀已经有效。"}, "42": {"keywords": ["KV State / Reuse"], "authors": "见原论文与精读笔记", "affiliation": "研究对象与机制见下文", "motivation": "协作模型对相同背景重复 prefill，而不同模型的 KV 不直接兼容。", "design": "离线 profiling 选择连续重算层，并传输额外中间状态。", "result": "同源模型对的长上下文质量与系统实验。", "limitations": "配置依赖模型对；profiling 和额外状态成本不能忽略。"}, "43": {"keywords": ["KV State / Reuse"], "authors": "见原论文与精读笔记", "affiliation": "研究对象与机制见下文", "motivation": "重复上下文不总是连续前缀。", "design": "管理上下文重叠、重排和复用；具体条件见已读笔记。", "result": "长上下文复用与开销实验，分别报告冷启动和单请求开销。", "limitations": "重叠识别、初始化成本与模型依赖要分开核算。"}, "44": {"keywords": ["KV State / Reuse"], "authors": "见原论文与精读笔记", "affiliation": "研究对象与机制见下文", "motivation": "语义近似但 token 序列不同的请求难以精确复用。", "design": "带位置的 embedding 匹配、KV 重排、逐层重算与 token retention。", "result": "参考文本删改实验和保留率消融。", "limitations": "模糊匹配与裁剪均有误差；不能解释为任意位置移动无须校正。"}, "45": {"keywords": ["KV State / Reuse"], "authors": "见原论文与精读笔记", "affiliation": "研究对象与机制见下文", "motivation": "并发 coding 会话长历史增长、工具等待与容量竞争导致重复 prefill。", "design": "前缀感知调度与复用时间预测驱逐。", "result": "公开脱敏 trace 有长度与时间信息；不等于公开真实 prompt 和任务答案。", "limitations": "长度与 cache_read 不能唯一恢复文本、编辑关系或 KV 因果有效性。"}, "46": {"keywords": ["KV State / Reuse"], "authors": "见原论文与精读笔记", "affiliation": "研究对象与机制见下文", "motivation": "长轮交互历史不断增长；粗粒度记忆压缩、维护和碎片读取抵消缩短输入的收益。", "design": "MemAttention 增量压缩、关联块联合更新与检索，并将相关记忆共置以减少碎片读取。", "result": "主结果与内存、服务开销分析见已读笔记。", "limitations": "语义记忆整理与 KV 数值复用不同；必须计入生成、维护和检索记忆的成本。"}, "47": {"keywords": ["Application–Engine Codesign"], "authors": "见原论文与精读笔记", "affiliation": "研究对象与机制见下文", "motivation": "工作流、模型与硬件配置写死在应用中。", "design": "声明式 workflow、profiling 优化与运行时配置。", "result": "多目标端到端配置实验。", "limitations": "不是新的 KV 数值复用方法。"}, "48": {"keywords": ["KV State / Reuse"], "authors": "见原论文与精读笔记", "affiliation": "研究对象与机制见下文", "motivation": "分层缓存命中后加载仍可能阻塞 batch。", "design": "分层 KV 数据面与 I/O-aware scheduler。", "result": "长上下文、多层存储的系统评测。", "limitations": "加载收益受带宽和缓存状态约束。"}, "49": {"keywords": ["Application–Engine Codesign"], "authors": "见原论文与精读笔记", "affiliation": "研究对象与机制见下文", "motivation": "孤立模型调用丢失应用数据依赖。", "design": "查询计划、共享与缓存感知执行。", "result": "可组合应用的端到端优化。", "limitations": "计划结构不等于任意动态 coding 历史。"}, "50": {"keywords": ["KV State / Reuse"], "authors": "见原论文与精读笔记", "affiliation": "研究对象与机制见下文", "motivation": "固定 token 重要性规则难泛化。", "design": "离线学习 per-head 保留排序。", "result": "多缓存预算下的质量实验。", "limitations": "有损 token 裁剪不等于前缀缓存 LRU。"}, "51": {"keywords": ["Application–Engine Codesign"], "authors": "见原论文与精读笔记", "affiliation": "研究对象与机制见下文", "motivation": "固定模型映射难适应 workflow 质量和延迟目标。", "design": "just-in-time model routing。", "result": "模型配置与任务执行评估。", "limitations": "跨模型 KV 转换不是默认免费的。"}, "52": {"keywords": ["Application–Engine Codesign"], "authors": "见原论文与精读笔记", "affiliation": "研究对象与机制见下文", "motivation": "工具等待与阶段状态影响工作流调度。", "design": "state-aware workflow scheduling。", "result": "状态与调度策略实验。", "limitations": "需与已有预测与暂停恢复方案比对。"}, "53": {"keywords": ["Application–Engine Codesign"], "authors": "见原论文与精读笔记", "affiliation": "研究对象与机制见下文", "motivation": "普通调用接口隐藏依赖和可管理状态。", "design": "future、managed state 与两级控制。", "result": "端到端延迟、吞吐及控制面实验。", "limitations": "显式状态接口不直接证明 KV 兼容。"}, "54": {"keywords": ["Application–Engine Codesign"], "authors": "见原论文与精读笔记", "affiliation": "研究对象与机制见下文", "motivation": "跨工作流共享缺少可核验身份。", "design": "logical identity、execution identity 与 lineage。", "result": "多租户工作流执行实验。", "limitations": "算子逻辑相同不代表任意 KV 可以共享。"}, "55": {"keywords": ["Application–Engine Codesign"], "authors": "见原论文与精读笔记", "affiliation": "研究对象与机制见下文", "motivation": "逐请求调度丢失 workflow 连续性。", "design": "工作流级调度、affinity、公平性和缓存管理。", "result": "完成时间与吞吐的权衡。", "limitations": "更好完成时间可能牺牲峰值吞吐。"}, "56": {"keywords": ["Application–Engine Codesign"], "authors": "见原论文与精读笔记", "affiliation": "研究对象与机制见下文", "motivation": "保留长前缀与推进 ready 请求争用显存。", "design": "联合入场、搬运、重算与撤销，以剩余路径为目标。", "result": "合成和 MetaGPT 类 workflow。", "limitations": "依赖可用的工作流结构与代价估计。"}, "57": {"keywords": ["Application–Engine Codesign"], "authors": "见原论文与精读笔记", "affiliation": "研究对象与机制见下文", "motivation": "异构阶段混跑产生资源干扰。", "design": "按 workflow stage 划分资源池。", "result": "架构及有限原型证据。", "limitations": "证据强度不足以与完整系统加速并列。"}, "58": {"keywords": ["Application–Engine Codesign"], "authors": "见原论文与精读笔记", "affiliation": "研究对象与机制见下文", "motivation": "不同阶段的 KV 通信竞争同一链路。", "design": "分阶段 flow 与优先级调度。", "result": "disaggregated serving 的 TTFT SLO。", "limitations": "后端通信优化，不管理应用上下文语义。"}, "59": {"keywords": ["KV State / Reuse"], "authors": "见原论文与精读笔记", "affiliation": "研究对象与机制见下文", "motivation": "过去 attention 不足以判断历史的独有信息。", "design": "counter-causal surprise 与周期评分。", "result": "长上下文与多模型质量测量。", "limitations": "token 近似裁剪；需要核算评分成本。"}, "60": {"keywords": ["Application–Engine Codesign"], "authors": "见原论文与精读笔记", "affiliation": "研究对象与机制见下文", "motivation": "Harness 掌握依赖与未来意图，Engine 掌握真实缓存与压力，两侧割裂。", "design": "四类消息与控制语义连接两侧；在线缓存协调与冻结角色配置作为实例。", "result": "SCBench Guard-40 整体 1.61×；BCP／DRB 所选配置 1.23×／2.45×。", "limitations": "性能回放与真实任务质量分开；协议承接策略，不提出非前缀修复。"}, "61": {"keywords": ["KV State / Reuse"], "authors": "见原论文与精读笔记", "affiliation": "研究对象与机制见下文", "motivation": "主动删除、替换与压缩历史让普通前缀缓存失效。", "design": "显式编辑四元组；amortize 保留旧影响、校正位置，forget 重新 prefill。", "result": "splice 命中＋11.2 pp／延迟最多−241 ms；debug-gym 策略＋14.3 pp。", "limitations": "MLA kernel 是主要验证路径；旋转不消除旧因果影响；两条实验不能合并。"}, "62": {"keywords": ["Application–Engine Codesign"], "authors": "见原论文与精读笔记", "affiliation": "研究对象与机制见下文", "motivation": "token 路由算法节省的大模型计算被模型切换与组批开销抵消。", "design": "独立 subserver、pending 状态、异步执行和延迟组批。", "result": "AIME 与 SWE-Smith 负载；生成吞吐和请求延迟。", "limitations": "各模型保留自己的 KV，不互换数值；不能推断端到端 SWE 解决率。"}, "63": {"keywords": ["KV State / Reuse"], "authors": "见原论文与精读笔记", "affiliation": "研究对象与机制见下文", "motivation": "关注 Agent 上下文的生命周期与状态变化。", "design": "harness 消息操作与子 agent 生命周期映射为活跃、闲置和死亡缓存。", "result": "coding trace 的多层缓存实验。", "limitations": "内容死亡与 KV 因果有效是两回事。"}, "64": {"keywords": ["KV State / Reuse"], "authors": "见原论文与精读笔记", "affiliation": "研究对象与机制见下文", "motivation": "关注 Agent 上下文的生命周期与状态变化。", "design": "复用工作集与 CPU admission，避免写入后未读就淘汰。", "result": "SWE-bench／OpenHands；回放与真实运行分开。", "limitations": "CPU 相同预算不代表有效缓存机会相同。"}, "65": {"keywords": ["上下文编辑", "批量提交", "缓存成本"], "authors": "Junjie Yao、Zhangchen Zhou、Zhi-Qin John Xu", "affiliation": "上海交通大学", "motivation": "结构化工具结果可外置，但每次替换都会使编辑点之后的前缀缓存失效；立即缩短输入未必降低输入成本。", "design": "原始对象保留不可变版本，Card 支持按需精确取回；将可替换与正式提交分开，累计等待成本达到共享后缀重建成本时批量提交。", "result": "Terminal-Bench 2.1、LongMemEval-V2、SWE-bench Verified 连续任务链的加权输入成本分别减少 47.13%、42.40%、34.12%；完成数为 36/89、10/18、29/50。", "limitations": "指标是缓存读取权重下的输入成本，不能等同 GPU 加速；相对 FULL，两组代码任务完成数略降。"}, "66": {"keywords": ["Lookahead", "上下文转换", "前后台协同"], "authors": "Zaifeng Pan、Qianxu Wang、Zhengding Hu、Chang Chen、Yue Guan、Yanbo Zhou、Steven Swanson、Yufei Ding", "affiliation": "加州大学圣迭戈分校", "motivation": "达到上下文阈值后才同步转换并重建 KV，会使长轮 Agent 在转换点出现 TTFT 尖峰。", "design": "主状态继续执行，lookahead 状态提前转换稳定片段并准备 KV；引擎按前台 TTFT/TBT 预算准入后台 chunk，抑制干扰。", "result": "28 步 MiniAgent 代码库分析中，Qwen3-8B/32B 的转换点 tail TTFT 平均降低 62.0%/61.5%；摘要策略最高改善 11.9 倍。", "limitations": "收益针对转换点 TTFT，不是完整任务加速；需要可分段转换及额外计算、KV 容量。PDF 的 PVLDB 信息为占位格式，当前按 arXiv 记录。"}, "67": {"keywords": ["KV State / Reuse"], "authors": "见原论文与精读笔记", "affiliation": "研究对象与机制见下文", "motivation": "关注 Agent 上下文的修复与状态变化。", "design": "固定当前 prompt 后改变缓存经历，检验修复跨轮历史敏感性。", "result": "滚动文档字段提取，不是 coding。", "limitations": "分叉输入的 F1 不能隔离缓存状态误差。"}, "68": {"keywords": ["KV State / Reuse"], "authors": "见原论文与精读笔记", "affiliation": "研究对象与机制见下文", "motivation": "关注 Agent 上下文的版本与状态变化。", "design": "记录文件、符号和测试证据版本，恢复前核验仓库。", "result": "DeepSWE／SWE-EVO／SWE-Milestone。", "limitations": "证据有效不等于 KV 精确有效。"}, "69": {"keywords": ["KV State / Reuse"], "authors": "见原论文与精读笔记", "affiliation": "研究对象与机制见下文", "motivation": "关注 Agent 上下文的修复与状态变化。", "design": "使用生产者 decode 已生成 KV，交给接收者修复。", "result": "GSM8K、MMLU、HumanEval；效率另设受控负载。", "limitations": "不保证普通追加会话有额外收益。"}, "70": {"keywords": ["KV State / Reuse"], "authors": "见原论文与精读笔记", "affiliation": "研究对象与机制见下文", "motivation": "关注 Agent 上下文的生命周期与状态变化。", "design": "阶段 query buffer 指导 token 保留与物理页面回收。", "result": "BFCL、τ²-bench；吞吐另设 workload。", "limitations": "有损 token 淘汰与前缀缓存淘汰不同。"}, "71": {"keywords": ["KV State / Reuse"], "authors": "见原论文与精读笔记", "affiliation": "研究对象与机制见下文", "motivation": "关注 Agent 上下文的版本与状态变化。", "design": "版本发布权限、旧输出阻止、有效前缀继承与异步回收。", "result": "修订与回收压力场景。", "limitations": "不能将取消＋保留 KV 作为未研究空白。"}, "72": {"keywords": ["KV State / Reuse"], "authors": "见原论文与精读笔记", "affiliation": "研究对象与机制见下文", "motivation": "关注 Agent 上下文的生命周期与状态变化。", "design": "读取工具运行进度指导缓存保留与恢复。", "result": "SWE trace 的工具尾部等待。", "limitations": "单独提前恢复仍属预取，不能直接作为新大方向。"}, "73": {"keywords": ["KV State / Reuse"], "authors": "见原论文与精读笔记", "affiliation": "研究对象与机制见下文", "motivation": "关注 Agent 上下文的编辑与状态变化。", "design": "版本对齐、dirty region 与选择性恢复。", "result": "构造的编辑 QA、多模型。", "limitations": "profile 与元数据有成本；不是长轮 coding 的完整证明。"}, "74": {"keywords": ["KV State / Reuse"], "authors": "见原论文与精读笔记", "affiliation": "研究对象与机制见下文", "motivation": "关注 Agent 上下文的修复与状态变化。", "design": "resource-wise attention 与局部位置让 tool／skill KV 可组合。", "result": "公开工具与 skill 数据源。", "limitations": "需训练适配，不是冻结 Mistral 插件。"}, "75": {"keywords": ["KV State / Reuse"], "authors": "见原论文与精读笔记", "affiliation": "研究对象与机制见下文", "motivation": "关注 Agent 上下文的生命周期与状态变化。", "design": "轮转 idle agent、从尾部淘汰，保护更多连续前缀。", "result": "SGLang 的追加历史竞争。", "limitations": "先检查较好的精确保留基线，再判断近似复用机会。"}, "76": {"keywords": ["KV State / Reuse"], "authors": "见原论文与精读笔记", "affiliation": "研究对象与机制见下文", "motivation": "关注 Agent 上下文的生命周期与状态变化。", "design": "层次 KV 准备与混合上下文执行的 admission 协调。", "result": "coding agent serving。", "limitations": "独立构建异步化可能只是适配修正。"}, "77": {"keywords": ["对象生命周期", "恢复指针", "旁路规划"], "authors": "Xubin Hao、Hongjin Meng、Xin Yin、Jiawei Zhu、Chenpeng Cao", "affiliation": "小红书", "motivation": "长轮工具轨迹包含精确路径、URL、表格值和编辑产物；按时间裁剪或自由摘要可能丢失后续依赖及恢复入口。", "design": "为历史对象分配稳定 ID；旁路 LLM 规划 Fold、Mask、Prune，harness 验证与预演后在安全边界提交，Fold 保留原文 sidecar 和恢复指针。", "result": "332 条生产会话上三个 planner 删除 31.04%–33.98% token，未来依赖 no-impact 为 91.27%–94.58%；在线主 Agent 平均输入减少约 10%–15%。", "limitations": "no-impact 是离线裁判对依赖保留的判断，不是任务成功率；原始生产轨迹不公开，在线分组非随机。"}});
Object.assign(PAPER_NOTES,{"41": "独立文档 KV、位置校正与选择性 token 重算，并重叠加载和计算。 额外独立构建、修复和搬运必须计入；追加历史完整驻留时原生前缀已经有效。", "42": "离线 profiling 选择连续重算层，并传输额外中间状态。 配置依赖模型对；profiling 和额外状态成本不能忽略。", "43": "管理上下文重叠、重排和复用；具体条件见已读笔记。 重叠识别、初始化成本与模型依赖要分开核算。", "44": "带位置的 embedding 匹配、KV 重排、逐层重算与 token retention。 模糊匹配与裁剪均有误差；不能解释为任意位置移动无须校正。", "45": "前缀感知调度与复用时间预测驱逐。 长度与 cache_read 不能唯一恢复文本、编辑关系或 KV 因果有效性。", "46": "MemAttention 增量压缩、关联块联合更新与检索，并将相关记忆共置以减少碎片读取。 语义记忆整理与 KV 数值复用不同；必须计入生成、维护和检索记忆的成本。", "47": "声明式 workflow、profiling 优化与运行时配置。 不是新的 KV 数值复用方法。", "48": "分层 KV 数据面与 I/O-aware scheduler。 加载收益受带宽和缓存状态约束。", "49": "查询计划、共享与缓存感知执行。 计划结构不等于任意动态 coding 历史。", "50": "离线学习 per-head 保留排序。 有损 token 裁剪不等于前缀缓存 LRU。", "51": "just-in-time model routing。 跨模型 KV 转换不是默认免费的。", "52": "state-aware workflow scheduling。 需与已有预测与暂停恢复方案比对。", "53": "future、managed state 与两级控制。 显式状态接口不直接证明 KV 兼容。", "54": "logical identity、execution identity 与 lineage。 算子逻辑相同不代表任意 KV 可以共享。", "55": "工作流级调度、affinity、公平性和缓存管理。 更好完成时间可能牺牲峰值吞吐。", "56": "联合入场、搬运、重算与撤销，以剩余路径为目标。 依赖可用的工作流结构与代价估计。", "57": "按 workflow stage 划分资源池。 证据强度不足以与完整系统加速并列。", "58": "分阶段 flow 与优先级调度。 后端通信优化，不管理应用上下文语义。", "59": "counter-causal surprise 与周期评分。 token 近似裁剪；需要核算评分成本。", "60": "四类消息与控制语义连接两侧；在线缓存协调与冻结角色配置作为实例。 性能回放与真实任务质量分开；协议承接策略，不提出非前缀修复。", "61": "显式编辑四元组；amortize 保留旧影响、校正位置，forget 重新 prefill。 MLA kernel 是主要验证路径；旋转不消除旧因果影响；两条实验不能合并。", "62": "独立 subserver、pending 状态、异步执行和延迟组批。 各模型保留自己的 KV，不互换数值；不能推断端到端 SWE 解决率。", "63": "harness 消息操作与子 agent 生命周期映射为活跃、闲置和死亡缓存。 内容死亡与 KV 因果有效是两回事。", "64": "复用工作集与 CPU admission，避免写入后未读就淘汰。 CPU 相同预算不代表有效缓存机会相同。", "65": "原始对象保留不可变版本，Card 支持按需精确取回；将可替换与正式提交分开，累计等待成本达到共享后缀重建成本时批量提交。 指标是缓存读取权重下的输入成本，不能等同 GPU 加速；相对 FULL，两组代码任务完成数略降。", "66": "主状态继续执行，lookahead 状态提前转换稳定片段并准备 KV；引擎按前台 TTFT/TBT 预算准入后台 chunk，抑制干扰。 收益针对转换点 TTFT，不是完整任务加速；需要可分段转换及额外计算、KV 容量。PDF 的 PVLDB 信息为占位格式，当前按 arXiv 记录。", "67": "固定当前 prompt 后改变缓存经历，检验修复跨轮历史敏感性。 分叉输入的 F1 不能隔离缓存状态误差。", "68": "记录文件、符号和测试证据版本，恢复前核验仓库。 证据有效不等于 KV 精确有效。", "69": "使用生产者 decode 已生成 KV，交给接收者修复。 不保证普通追加会话有额外收益。", "70": "阶段 query buffer 指导 token 保留与物理页面回收。 有损 token 淘汰与前缀缓存淘汰不同。", "71": "版本发布权限、旧输出阻止、有效前缀继承与异步回收。 不能将取消＋保留 KV 作为未研究空白。", "72": "读取工具运行进度指导缓存保留与恢复。 单独提前恢复仍属预取，不能直接作为新大方向。", "73": "版本对齐、dirty region 与选择性恢复。 profile 与元数据有成本；不是长轮 coding 的完整证明。", "74": "resource-wise attention 与局部位置让 tool／skill KV 可组合。 需训练适配，不是冻结 Mistral 插件。", "75": "轮转 idle agent、从尾部淘汰，保护更多连续前缀。 先检查较好的精确保留基线，再判断近似复用机会。", "76": "层次 KV 准备与混合上下文执行的 admission 协调。 独立构建异步化可能只是适配修正。", "77": "为历史对象分配稳定 ID；旁路 LLM 规划 Fold、Mask、Prune，harness 验证与预演后在安全边界提交，Fold 保留原文 sidecar 和恢复指针。 no-impact 是离线裁判对依赖保留的判断，不是任务成功率；原始生产轨迹不公开，在线分组非随机。"});
PHASE_GROUPS.push(...[{"number": "PHASE 04", "period": "补充调研 · 2026-09 → 2026-10", "title": "从前缀复用到块级修复与完整 Agent 执行", "thesis": "按研究问题归类，阶段区间是本地调研进度；论文首次公开时间见每条记录。区分缓存命中、计算节省、任务质量与端到端收益。", "lanes": [{"title": "块级、语义与跨模型 KV 复用", "ids": [41, 42, 43, 44, 67, 69, 74]}, {"title": "Coding 负载、缓存执行与数据面", "ids": [45, 46, 48, 64, 75, 76]}, {"title": "Workflow 表达、配置与整体执行", "ids": [47, 49, 51, 52, 53, 54, 55, 56, 57, 58, 62]}]}, {"number": "PHASE 05", "period": "方向复审 · 更新至 2026-10-19", "title": "Harness–Engine 协同与 Agent 上下文生命周期", "thesis": "分开记录两条相关但不同的研究线：Topic1 聚焦 Harness 与推理引擎的跨层协同；Topic2 聚焦上下文演化及 KV 状态生命周期。相关工作可以交叉引用，问题定义和方案不混写。Topic1 的具体缺口尚未收敛。", "lanes": [{"title": "Topic1 · Harness–Engine 协同", "ids": [60]}, {"title": "Topic2 · 上下文演化与 KV 状态", "ids": [61, 65, 66, 73, 77, 63]}, {"title": "相关运行时与状态管理工作", "ids": [50, 59, 68, 70, 71, 72]}]}]);
